-- Critério de pronto vira módulo por projeto (ADR-10). Projetos que já têm itens da definição de pronto ganham o módulo `definitionOfDone` ativo, para a conferência ao concluir e o editor continuarem valendo. Projeto sem itens não ganha linha. Nada é apagado; se a linha já existia, só o estado vira 'active' e a configuração é preservada.
INSERT INTO `project_modules` (`organization_id`, `project_id`, `module_id`, `state`, `config`, `changed_by`, `changed_at`) SELECT DISTINCT `definition_of_done_items`.`organization_id`, `definition_of_done_items`.`project_id`, 'definitionOfDone', 'active', NULL, NULL, NULL FROM `definition_of_done_items` WHERE 1 ON CONFLICT(`project_id`, `module_id`) DO UPDATE SET `state` = 'active';
